#!/usr/bin/env python3
"""JSON entry point. Repair the package and implement its replay extension."""
import json
import math
import sys
from crosscheck import CrossCheck

def pairs(items):
    result = {}
    for k,v in items:
        if k in result: raise ValueError("duplicate key")
        result[k] = v
    return result

def finite(value):
    result=float(value)
    if not math.isfinite(result):raise ValueError("nonfinite number")
    return result

def main():
    try:
        request = json.loads(sys.stdin.buffer.read().decode("utf-8"), object_pairs_hook=pairs, parse_float=finite,
                             parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
    except (ValueError, UnicodeError):
        print('{"error":"invalid_json"}')
        return
    results=[]
    for stream in request["streams"]:
        engine=CrossCheck(stream["topology"])
        results.append({"events":engine.replay(stream["events"],stream["settings"])})
    print(json.dumps({"streams":results},separators=(",",":"),allow_nan=False))

if __name__ == "__main__": main()

#!/usr/bin/env python3
"""Public examples only. Executes frozen candidate bytes in bounded children."""
import json
import math
import os
from pathlib import Path
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
from limits import restrict_child

def strict_json(data):
    def pairs(items):
        out={}
        for k,v in items:
            if k in out:raise ValueError('duplicate key')
            out[k]=v
        return out
    def finite(v):
        x=float(v)
        if not math.isfinite(x):raise ValueError('nonfinite number')
        return x
    return json.loads(data.decode('utf-8'),object_pairs_hook=pairs,parse_float=finite,
                      parse_constant=lambda v:(_ for _ in ()).throw(ValueError(v)))


class CheckInterrupted(RuntimeError):
    pass


def run_child(path, data, temp):
    scratch = temp / 'scratch'
    scratch.mkdir()
    env = {'PATH': '/usr/local/bin:/usr/bin:/bin', 'HOME': '/workspace',
           'LANG': 'C', 'LC_ALL': 'C', 'TMPDIR': str(scratch),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONUNBUFFERED': '1',
           'PYTHONHASHSEED': '0', 'OMP_NUM_THREADS': '1',
           'OPENBLAS_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1', 'PYTHONPATH':'/opt/deps'}
    started = time.monotonic()
    child = subprocess.Popen([sys.executable, '-B', '-u', str(path)],
                             stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, cwd=scratch, env=env,
                             close_fds=True, start_new_session=True,
                             preexec_fn=restrict_child)
    sel = selectors.DefaultSelector()
    streams = [child.stdin, child.stdout, child.stderr]
    chunks = [bytearray(), bytearray()]
    offset = 0
    next_storage = started
    try:
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if data:
            sel.register(child.stdin, selectors.EVENT_WRITE, -1)
        else:
            child.stdin.close()
        sel.register(child.stdout, selectors.EVENT_READ, 0)
        sel.register(child.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now - started >= 180:
                raise ValueError('wall limit exceeded')
            if now >= next_storage:
                size, count = 0, 0
                for base, dirs, files in os.walk(scratch, followlinks=False):
                    for name in dirs + files:
                        st = (Path(base)/name).lstat()
                        count += 1
                        if stat.S_ISREG(st.st_mode):
                            size += max(st.st_size, st.st_blocks*512)
                if size > 64*1024**2 or count > 4096:
                    raise RuntimeError('infrastructure: scratch emergency budget')
                next_storage = now + .25
            for key, _ in sel.select(.05):
                stream, channel = key.fileobj, key.data
                if channel == -1:
                    try:
                        offset += os.write(stream.fileno(), data[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        offset = len(data)
                    if offset == len(data):
                        sel.unregister(stream)
                        stream.close()
                else:
                    cap = (8*1024**2, 1024**2)[channel]
                    try:
                        block = os.read(stream.fileno(), min(65536, cap-len(chunks[channel])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(chunks[channel])+len(block) > cap:
                        raise ValueError('output byte limit exceeded')
                    else:
                        chunks[channel].extend(block)
        code = child.wait(timeout=max(.001, 180-(time.monotonic()-started)))
        if code:
            raise ValueError('candidate returned nonzero')
        return strict_json(bytes(chunks[0]))
    finally:
        # Ignore repeated interrupts until this single no-fork child is reaped.
        previous = {sig: signal.signal(sig, signal.SIG_IGN)
                    for sig in (signal.SIGINT, signal.SIGTERM)}
        try:
            if child.poll() is None:
                child.kill()
            child.wait(timeout=5)
            sel.close()
            for stream in streams:
                stream.close()
            shutil.rmtree(scratch)
        finally:
            for sig, handler in previous.items():
                signal.signal(sig, handler)


def same(actual, expected):
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, dict):
        return actual.keys() == expected.keys() and all(same(actual[k], v) for k,v in expected.items())
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(same(a,b) for a,b in zip(actual,expected))
    return actual == expected


def freeze_tree(source, target):
    if source.is_symlink() or not source.is_dir():
        raise ValueError('submission must be a directory')
    target.mkdir()
    total=entries=0
    for base,dirs,files in os.walk(source,followlinks=False):
        relative=Path(base).relative_to(source)
        for name in dirs+files:
            path=Path(base)/name
            before=path.lstat()
            entries+=1
            if entries>256:raise ValueError('submission entry limit')
            if not (stat.S_ISDIR(before.st_mode) or stat.S_ISREG(before.st_mode)):
                raise ValueError('unsafe submission entry')
            destination=target/relative/name
            if stat.S_ISDIR(before.st_mode):
                destination.mkdir()
                continue
            if before.st_nlink!=1:raise ValueError('submission hard link')
            total+=before.st_size
            if total>2*1024**2:raise ValueError('submission byte limit')
            fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
            try:
                opened=os.fstat(fd)
                identity=lambda st:(st.st_dev,st.st_ino,st.st_size,st.st_mtime_ns)
                if identity(opened)!=identity(before):raise RuntimeError('submission changed')
                with os.fdopen(fd,'rb',closefd=False) as stream:
                    content=stream.read(before.st_size+1)
                if len(content)!=before.st_size or identity(os.fstat(fd))!=identity(before):
                    raise RuntimeError('submission changed')
                destination.write_bytes(content)
                destination.chmod(0o444)
            finally:os.close(fd)
    if not (target/'main.py').is_file():raise ValueError('main.py missing')
    for base,dirs,files in os.walk(target):Path(base).chmod(0o555)

def main():
    if os.geteuid() == 0:
        raise RuntimeError('refusing root: use an isolated local controller or the public image user')
    path = Path(sys.argv[1] if len(sys.argv)>1 else 'submission')
    fixtures = json.loads(Path(__file__).with_name('examples.json').read_text())
    def interrupted(signum, frame):
        raise CheckInterrupted('public check interrupted')
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, interrupted)
    with tempfile.TemporaryDirectory(prefix='wan-public-', dir=os.environ.get('TMPDIR'),ignore_cleanup_errors=True) as name:
        temp = Path(name)
        frozen = temp/'submission'
        freeze_tree(path,frozen)
        for fixture in fixtures:
            data = fixture.get('raw')
            if data is None:
                data = json.dumps(fixture['request'], separators=(',',':'))
            answer = run_child(frozen/'main.py', data.encode(), temp)
            if not same(answer,fixture['expected']):
                raise ValueError('public example failed: '+fixture['name'])
            print('PASS '+fixture['name'], flush=True)
    print('All public examples passed.')


if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        print(type(exc).__name__+': '+str(exc), file=sys.stderr)
        sys.exit(1)
