"""Routed demand prediction and external demand marginals.

With a routing plan an internal directed flow's predicted load is
``floor(sum(demand * path weight) / 1000)`` floored once after all
contributions.  External flows carry the full outgoing/incoming demand
marginal.  Results are never clamped here; callers clamp repair votes only.
"""

from .domain import DomainError

MILLION = 1000000


def normalize_routes(raw):
    """Canonical, order-independent identity of a routing plan (or None)."""
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise DomainError('paths must be an object or null')
    bundles = []
    for source_name, destinations in raw.items():
        if not isinstance(destinations, dict):
            raise DomainError('path bundle map must be an object')
        for dest_name, entries in destinations.items():
            if not isinstance(entries, list):
                raise DomainError('path bundle must be an array')
            items = []
            for entry in entries:
                if not isinstance(entry, dict):
                    raise DomainError('path entry must be an object')
                try:
                    path = entry['path']
                    weight = entry['weight']
                except KeyError as exc:
                    raise DomainError('path entry field %s missing' % exc)
                if not isinstance(path, list) or not isinstance(path[0], str):
                    raise DomainError('path must be an array of names')
                items.append((tuple(path), weight))
            items.sort()
            bundles.append(((source_name, dest_name), tuple(items)))
    bundles.sort()
    return tuple(bundles)


def external_marginals(topology, demands):
    """Return ``(outgoing, incoming)`` marginal maps keyed by node id."""
    outgoing = {}
    incoming = {}
    for (source, dest), value in demands.items():
        if value:
            outgoing[source] = outgoing.get(source, 0) + value
            incoming[dest] = incoming.get(dest, 0) + value
    return outgoing, incoming


def compute_predictions(topology, demands, routes):
    """Predicted load per flow pair.

    With ``routes`` None only the external flows (their demand marginals) are
    expected; internal flows have no expectation at all.
    """
    outgoing, incoming = external_marginals(topology, demands)
    predictions = {}
    if routes is None:
        for nid in topology.external_ids:
            predictions[(-1, nid)] = outgoing.get(nid, 0)
            predictions[(nid, -1)] = incoming.get(nid, 0)
        return predictions

    id_by_name = topology.id_by_name
    accumulators = {}
    for (source_name, dest_name), bundle in routes:
        source = id_by_name.get(source_name)
        dest = id_by_name.get(dest_name)
        if source is None or dest is None:
            continue
        demand = demands.get((source, dest), 0)
        if not demand:
            continue
        for path, weight in bundle:
            contribution = demand * weight
            previous = id_by_name.get(path[0])
            for vertex in path[1:]:
                current = id_by_name.get(vertex)
                if previous is None or current is None:
                    previous = current
                    continue
                hop = (previous, current)
                accumulators[hop] = accumulators.get(hop, 0) + contribution
                previous = current

    for source, target, _capacity in topology.flows:
        if source == -1:
            predictions[(source, target)] = outgoing.get(target, 0)
        elif target == -1:
            predictions[(source, target)] = incoming.get(source, 0)
        else:
            predictions[(source, target)] = \
                accumulators.get((source, target), 0) // MILLION
    return predictions
