"""Literal, brute-force reference implementation of the DTP repair.

Written directly from PROTOCOL.md, independently of the submission package.
Slow but simple: recomputes every flow's evidence from scratch at every prefix.
"""
import hashlib
from math import gcd


def ref_band(items, epsilon):
    """Literal agreement band. items = [(value, weight), ...]."""
    if not items:
        return None
    values = sorted(set(v for v, _ in items))
    best = None
    for i, lo in enumerate(values):
        for hi in values[i:]:
            if 1000000 * (hi - lo) <= epsilon * hi:
                weight = sum(w for v, w in items if lo <= v <= hi)
                key = (-weight, lo, hi)
                if best is None or key < best:
                    best = key
    if best is None:
        return None
    weight = -best[0]
    lo, hi = best[1], best[2]
    total = sum(v * w for v, w in items if lo <= v <= hi)
    return total // weight, weight


def ref_predictions(nodes, links, external, ext_cap, name_by_id, id_by_name,
                    demands, routes_raw):
    """Predicted loads. Returns dict pair->value (external only if no routes)."""
    flows = []
    for (a, b) in links:
        flows.append((a, b))
        flows.append((b, a))
    for nid in external:
        flows.append((-1, nid))
        flows.append((nid, -1))
    out_marg = {}
    in_marg = {}
    for (s, d), v in demands.items():
        if v:
            out_marg[s] = out_marg.get(s, 0) + v
            in_marg[d] = in_marg.get(d, 0) + v
    preds = {}
    if routes_raw is None:
        for nid in external:
            preds[(-1, nid)] = out_marg.get(nid, 0)
            preds[(nid, -1)] = in_marg.get(nid, 0)
        return preds
    acc = {}
    for sname, dests in routes_raw.items():
        for dname, plist in dests.items():
            sid = id_by_name[sname]
            did = id_by_name[dname]
            demand = demands.get((sid, did), 0)
            if not demand:
                continue
            for p in plist:
                contrib = demand * p['weight']
                path = p['path']
                prev = id_by_name[path[0]]
                for vtx in path[1:]:
                    cur = id_by_name[vtx]
                    acc[(prev, cur)] = acc.get((prev, cur), 0) + contrib
                    prev = cur
    for pair in flows:
        a, b = pair
        if a == -1:
            preds[pair] = out_marg.get(b, 0)
        elif b == -1:
            preds[pair] = in_marg.get(a, 0)
        else:
            preds[pair] = acc.get(pair, 0) // 1000
    return preds


def ref_pool(pair, cap, counters, preds, name_by_id):
    a, b = pair
    entries = []
    if a == -1:
        src = None
        dst = 'low_%s_origination' % name_by_id[b]
    elif b == -1:
        src = 'low_%s_termination' % name_by_id[a]
        dst = None
    else:
        src = 'low_%s_egress_to_%s' % (name_by_id[a], name_by_id[b])
        dst = 'low_%s_ingress_from_%s' % (name_by_id[b], name_by_id[a])
    if src is not None and src in counters:
        entries.append(counters[src])
    if dst is not None and dst in counters:
        entries.append(counters[dst])
    if preds is not None:
        entries.append(min(preds[pair], cap))
    return entries


def ref_repair(topo_spec, counters, demands, routes_raw, seed, trials, epsilon):
    """topo_spec: dict with nodes, links, external_nodes (raw request form)."""
    name_by_id = {n['id']: n['name'] for n in topo_spec['nodes']}
    id_by_name = {n['name']: n['id'] for n in topo_spec['nodes']}
    ext_cap = {}
    external = set()
    for name in topo_spec['external_nodes']:
        nid = id_by_name[name]
        external.add(nid)
        ext_cap[nid] = next(n['external_capacity'] for n in topo_spec['nodes']
                            if n['id'] == nid)
    links = set()
    cap_of = {}
    for l in topo_spec['links']:
        a, b = l['source'], l['target']
        links.add((a, b))
        links.add((b, a))
        cap_of[(a, b)] = l['capacity']
        cap_of[(b, a)] = l['capacity']
    flows = []
    for (a, b) in links:
        flows.append((a, b, cap_of[(a, b)]))
    for nid in external:
        flows.append((-1, nid, ext_cap[nid]))
        flows.append((nid, -1, ext_cap[nid]))
    flows.sort(key=lambda f: (f[0], f[1]))

    preds = ref_predictions(nodes=None, links=links, external=external,
                            ext_cap=ext_cap, name_by_id=name_by_id,
                            id_by_name=id_by_name, demands=demands,
                            routes_raw=routes_raw) if routes_raw is not None else None
    pools = {}
    caps = {}
    endpoints = {}
    for (a, b, cap) in flows:
        pools[(a, b)] = ref_pool((a, b), cap, counters, preds, name_by_id)
        caps[(a, b)] = cap
        if a == -1:
            endpoints[(a, b)] = [b]
        elif b == -1:
            endpoints[(a, b)] = [a]
        else:
            endpoints[(a, b)] = [a, b]
    routers = {}
    for (a, b, cap) in flows:
        if a != -1:
            routers.setdefault(a, []).append((a, b, True))
        if b != -1:
            routers.setdefault(b, []).append((a, b, False))

    def sampled(pair, router, trial):
        if pair in fixed:
            return fixed[pair]
        pool = pools[pair]
        if not pool:
            return 0
        text = '%d:%d:%d:%d:%d' % (seed, router, trial, pair[0], pair[1])
        w = int.from_bytes(
            hashlib.sha256(text.encode()).digest()[:8], 'big')
        return pool[w % len(pool)]

    fixed = {}
    order = []
    confs = {}
    values = {}
    remaining = [(f[0], f[1]) for f in flows]
    while remaining:
        best = None
        for pair in sorted(remaining):
            evidence = [(v, trials) for v in pools[pair]]
            for router in endpoints[pair]:
                rems = []
                for t in range(trials):
                    s_in = 0
                    s_out = 0
                    for (fa, fb, outgoing) in routers[router]:
                        v = sampled((fa, fb), router, t)
                        if outgoing:
                            s_out += v
                        else:
                            s_in += v
                    delta = s_in - s_out
                    target = sampled(pair, router, t)
                    if pair[0] == router:
                        x = delta + target
                    else:
                        x = -delta + target
                    cap = caps[pair]
                    x = min(max(x, 0), cap)
                    rems.append(x)
                got = ref_band([(x, 1) for x in rems], epsilon)
                if got is None:
                    continue
                evidence.append(got)
            res = ref_band(evidence, epsilon)
            cand, sup = res
            key = (-sup, pair)
            if best is None or key < best[0]:
                best = (key, cand, sup)
        (negsup, pair), cand, sup = best
        fixed[pair] = cand
        order.append(pair)
        values[pair] = cand
        g = gcd(sup, trials)
        if g < 1:
            g = 1
        confs[pair] = (sup // g, trials // g)
        remaining.remove(pair)
    return order, values, confs
