"""Random in-domain request / repair-input generator for cross-checking."""
import random
import string


def rand_name(rng, used):
    while True:
        n = rng.choice(string.ascii_uppercase) + ''.join(
            rng.choice(string.ascii_lowercase + string.digits)
            for _ in range(rng.randint(0, 8)))
        if n not in used:
            used.add(n)
            return n


def rand_fraction(rng, limit):
    d = rng.randint(1, 12)
    n = rng.randint(0, limit * d)
    return [n, d]


def make_topology(rng, max_nodes=6, max_links=8, max_ext=4, max_cap=1000):
    node_count = rng.randint(1, max_nodes)
    used = set()
    nodes = []
    for i in range(node_count):
        nodes.append({'id': i, 'name': rand_name(rng, used),
                      'external_capacity': rng.randint(0, max_cap)})
    rng.shuffle(nodes)
    ids = [n['id'] for n in nodes]
    links = []
    seen = set()
    for _ in range(rng.randint(0, max_links)):
        a, b = rng.sample(ids, 2)
        key = (min(a, b), max(a, b))
        if key in seen:
            continue
        seen.add(key)
        links.append({'source': a, 'target': b,
                      'capacity': rng.randint(0, max_cap)})
    ext_count = rng.randint(0, min(max_ext, node_count))
    by_id = {n['id']: n for n in nodes}
    external = [by_id[i]['name'] for i in rng.sample(ids, ext_count)]
    return {'nodes': nodes, 'links': links, 'external_nodes': external}


def simple_paths(topo, rng, max_paths=4):
    """Valid routing plan: every ordered pair of distinct external nodes."""
    id_by_name = {n['name']: n['id'] for n in topo['nodes']}
    adj = {}
    for l in topo['links']:
        adj.setdefault(l['source'], set()).add(l['target'])
        adj.setdefault(l['target'], set()).add(l['source'])
    names = list(topo['external_nodes'])
    plan = {}
    for s in names:
        for d in names:
            if s == d:
                continue
            # BFS for simple paths
            sid, did = id_by_name[s], id_by_name[d]
            found = []
            stack = [[sid]]
            while stack and len(found) < 40:
                path = stack.pop()
                if path[-1] == did:
                    found.append(path)
                    continue
                for nxt in adj.get(path[-1], ()):
                    if nxt not in path:
                        stack.append(path + [nxt])
            if not found:
                return None
            rng.shuffle(found)
            chosen = found[:rng.randint(1, min(max_paths, len(found)))]
            bundles = []
            for path in chosen:
                if len(path) > 33:
                    continue
                bundles.append([id_by_name and n for n in
                                [None]] if False else path)
            if not bundles:
                bundles = [found[0]]
            weights = []
            total = 1000
            for i in range(len(bundles) - 1):
                w = rng.randint(1, max(1, total - (len(bundles) - 1 - i)))
                weights.append(w)
                total -= w
            weights.append(total)
            entries = []
            for path, w in zip(bundles, weights):
                entries.append({'path': [next(n['name'] for n in topo['nodes']
                                             if n['id'] == p) for p in path],
                                'weight': w})
            plan.setdefault(s, {})[d] = entries
    return plan if plan else {}


def counter_keys(topo):
    id_by_name = {n['name']: n['id'] for n in topo['nodes']}
    name_by_id = {n['id']: n['name'] for n in topo['nodes']}
    keys = []
    for l in topo['links']:
        a, b = l['source'], l['target']
        keys.append('low_%s_egress_to_%s' % (name_by_id[a], name_by_id[b]))
        keys.append('low_%s_ingress_from_%s' % (name_by_id[b], name_by_id[a]))
    for name in topo['external_nodes']:
        keys.append('low_%s_origination' % name)
        keys.append('low_%s_termination' % name)
    caps = {}
    for l in topo['links']:
        a, b = l['source'], l['target']
        caps['low_%s_egress_to_%s' % (name_by_id[a], name_by_id[b])] = l['capacity']
        caps['low_%s_ingress_from_%s' % (name_by_id[b], name_by_id[a])] = l['capacity']
    by_name = {n['name']: n for n in topo['nodes']}
    for name in topo['external_nodes']:
        caps['low_%s_origination' % name] = by_name[name]['external_capacity']
        caps['low_%s_termination' % name] = by_name[name]['external_capacity']
    return keys, caps


def make_state(rng, topo, max_counter_vals=8, max_demands=6, max_tick=1000):
    keys, caps = counter_keys(topo)
    counters = {}
    for key in keys:
        if rng.random() < 0.5:
            counters[key] = rng.randint(0, caps[key])
    demands = {}
    ext = list(topo['external_nodes'])
    id_by_name = {n['name']: n['id'] for n in topo['nodes']}
    if len(ext) >= 2:
        for _ in range(rng.randint(0, max_demands)):
            s, d = rng.sample(ext, 2)
            demands[(id_by_name[s], id_by_name[d])] = rng.randint(0, max_tick)
    return counters, demands
