"""Independent reference implementation of the whole stream replay."""
import sys
from math import gcd

sys.path.insert(0, '/workspace/dev')
import ref as refcore

MILLION = 1000000


def _is_int(x):
    return type(x) is int


def valid_counter_keys(topo):
    name_by_id = {n['id']: n['name'] for n in topo['nodes']}
    id_by_name = {n['name']: n['id'] for n in topo['nodes']}
    keys = {}
    for l in topo['links']:
        a, b = l['source'], l['target']
        keys['low_%s_egress_to_%s' % (name_by_id[a], name_by_id[b])] = (a, b, l['capacity'])
        keys['low_%s_ingress_from_%s' % (name_by_id[b], name_by_id[a])] = (a, b, l['capacity'])
    by_name = {n['name']: n for n in topo['nodes']}
    for name in topo['external_nodes']:
        nid = id_by_name[name]
        cap = by_name[name]['external_capacity']
        keys['low_%s_origination' % name] = (-1, nid, cap)
        keys['low_%s_termination' % name] = (nid, -1, cap)
    return keys


def norm_routes(raw):
    if raw is None:
        return None
    items = []
    for s, dests in raw.items():
        for d, plist in dests.items():
            for p in plist:
                items.append(((s, d), tuple(p['path']), p['weight']))
    return tuple(sorted(items))


def norm_topo(topo):
    nodes = tuple(sorted((n['id'], n['name'], n['external_capacity'])
                         for n in topo['nodes']))
    links = tuple(sorted((min(l['source'], l['target']),
                          max(l['source'], l['target']), l['capacity'])
                         for l in topo['links']))
    external = tuple(sorted(topo['external_nodes']))
    return (nodes, links, external)


class RefStream:
    def __init__(self, topo, settings):
        self.topo = topo
        self.trials = settings['trials']
        self.epsilon = settings['epsilon']
        self.seed = settings['seed']
        self.cutoff = tuple(settings['cutoff'])
        self.bias = settings['bias']
        self.tau = settings['tau']
        self.gamma = tuple(settings['gamma'])
        self.slots = settings['cache_slots']
        self.demands = {}
        self.counters = {}
        self.routes_raw = None
        self.snapshots = {}
        self.cache = {}
        self.order = []

    def key(self):
        return (norm_topo(self.topo),
                tuple(sorted(self.counters.items())),
                tuple(sorted((k, v) for k, v in self.demands.items() if v)),
                norm_routes(self.routes_raw),
                self.seed, self.trials, self.epsilon)

    def replay(self, events):
        out = []
        for ev in events:
            if ev['op'] == 'patch':
                out.append(self.patch(ev))
            elif ev['op'] == 'routes':
                self.routes_raw = ev['paths']
                out.append({'op': 'routes', 'accepted': True})
            elif ev['op'] == 'repair':
                out.append(self.repair(ev['id']))
            elif ev['op'] == 'validate':
                out.append(self.validate(ev['id']))
        return out

    def patch(self, ev):
        if set(ev.keys()) != {'op', 'demands', 'counters'}:
            return {'op': 'patch', 'accepted': False}
        dem = ev['demands']
        cnt = ev['counters']
        if not isinstance(dem, list) or not isinstance(cnt, dict):
            return {'op': 'patch', 'accepted': False}
        id_by_name = {n['name']: n['id'] for n in self.topo['nodes']}
        external = set(id_by_name[n] for n in self.topo['external_nodes'])
        new_dem = {}
        for entry in dem:
            if not isinstance(entry, list) or len(entry) != 3:
                return {'op': 'patch', 'accepted': False}
            s, d, v = entry
            if not (_is_int(s) and _is_int(d) and _is_int(v)):
                return {'op': 'patch', 'accepted': False}
            if s not in external or d not in external or s == d:
                return {'op': 'patch', 'accepted': False}
            if v < 0 or v > 10 ** 9:
                return {'op': 'patch', 'accepted': False}
            if (s, d) in new_dem:
                return {'op': 'patch', 'accepted': False}
            new_dem[(s, d)] = v
        keys = valid_counter_keys(self.topo)
        new_cnt = {}
        for k, cell in cnt.items():
            if k not in keys:
                return {'op': 'patch', 'accepted': False}
            if cell is None:
                new_cnt[k] = None
                continue
            if not isinstance(cell, dict):
                return {'op': 'patch', 'accepted': False}
            if 'perturbed' not in cell:
                return {'op': 'patch', 'accepted': False}
            if not set(cell.keys()) <= {'perturbed', 'ground_truth',
                                        'corrected', 'confidence'}:
                return {'op': 'patch', 'accepted': False}
            p = cell['perturbed']
            if p is None:
                new_cnt[k] = None
                continue
            if not _is_int(p):
                return {'op': 'patch', 'accepted': False}
            cap = keys[k][2]
            if p < 0 or p > cap:
                return {'op': 'patch', 'accepted': False}
            new_cnt[k] = p
        for k, v in new_dem.items():
            self.demands[k] = v
        for k, v in new_cnt.items():
            if v is None:
                self.counters.pop(k, None)
            else:
                self.counters[k] = v
        return {'op': 'patch', 'accepted': True}

    def repair(self, rid):
        key = self.key()
        hit = key in self.cache
        if hit:
            result = self.cache[key]
            self.order.remove(key)
            self.order.append(key)
        else:
            result = refcore.ref_repair(self.topo, self.counters, self.demands,
                                        self.routes_raw, self.seed,
                                        self.trials, self.epsilon)
            if self.slots:
                self.cache[key] = result
                self.order.append(key)
                while len(self.cache) > self.slots:
                    old = self.order.pop(0)
                    del self.cache[old]
        self.snapshots[rid] = result
        order, values, confs = result
        name_by_id = {n['id']: n['name'] for n in self.topo['nodes']}
        keys = valid_counter_keys(self.topo)
        flows = sorted(set((k[0], k[1]) for k in keys.values()))
        links = []
        for pair in flows:
            v = values[pair]
            n, d = confs[pair]
            links.append([pair[0], pair[1], v, n, d])
        counters = {}
        for key in keys:
            pair = (keys[key][0], keys[key][1])
            counters[key] = {'corrected': values[pair],
                             'confidence': list(confs[pair])}
        return {'op': 'repair', 'id': rid, 'cache_hit': hit,
                'links': links, 'order': [[p[0], p[1]] for p in order],
                'counters': counters}

    def validate(self, rid):
        order, values, confs = self.snapshots[rid]
        name_by_id = {n['id']: n['name'] for n in self.topo['nodes']}
        id_by_name = {n['name']: n['id'] for n in self.topo['nodes']}
        keys = valid_counter_keys(self.topo)
        preds = refcore.ref_predictions(None, set(keys2 for keys2 in ()),
                                        set(id_by_name[n] for n in self.topo['external_nodes']),
                                        None, name_by_id, id_by_name,
                                        self.demands, self.routes_raw)
        checked = passed = 0
        failed = []
        cut_n, cut_d = self.cutoff
        for key, (a, b, cap) in keys.items():
            pair = (a, b)
            if self.routes_raw is None and a != -1 and b != -1:
                continue
            if pair not in preds:
                continue
            n, d = confs[pair]
            if n * cut_d < cut_n * d:
                continue
            checked += 1
            X = values[pair] * MILLION
            Y = preds[pair] * (MILLION - self.bias)
            if MILLION * abs(X - Y) <= self.tau * max(X, Y):
                passed += 1
            else:
                failed.append(key)
        failed.sort()
        consistent = None
        if checked:
            gn, gd = self.gamma
            consistent = passed * gd >= checked * gn
        return {'op': 'validate', 'id': rid, 'checked': checked,
                'passed': passed, 'consistent': consistent, 'failed': failed}


def run_reference(request):
    out = []
    for stream in request['streams']:
        st = RefStream(stream['topology'], stream['settings'])
        out.append({'events': st.replay(stream['events'])})
    return {'streams': out}
