"""Replay engine: persistent inputs, events, memoised repairs and validation.

Each stream owns independent state: sparse demand/counter inputs, the active
routing plan, frozen repair snapshots and a capacity-bounded repair cache
keyed on the semantic inputs only.
"""

from collections import OrderedDict

from .domain import DomainError, MAX_TICKS, require_fraction, require_int
from .predictions import compute_predictions, normalize_routes
from .repair import compute_repair
from .topology import Topology

MILLION = 1000000
PATCH_FIELDS = frozenset(('op', 'demands', 'counters'))
CELL_ANNOTATIONS = frozenset(('perturbed', 'ground_truth', 'corrected',
                              'confidence'))


class StreamState:
    """Mutable per-stream replay state."""

    def __init__(self, topology_raw, settings_raw):
        if not isinstance(settings_raw, dict):
            raise DomainError('settings must be an object')
        for field in ('trials', 'epsilon', 'seed', 'cutoff', 'bias', 'tau',
                      'gamma', 'cache_slots'):
            if field not in settings_raw:
                raise DomainError('settings field %s missing' % field)
        self.topo = Topology(topology_raw)

        self.trials = require_int(settings_raw['trials'], 1, 32, 'trials')
        self.epsilon = require_int(settings_raw['epsilon'], 0, 250000, 'epsilon')
        self.seed = require_int(settings_raw['seed'], 0, 4294967295, 'seed')
        self.cutoff = require_fraction(settings_raw['cutoff'], 5, 1, 'cutoff')
        self.bias = require_int(settings_raw['bias'], 0, 1000000, 'bias')
        self.tau = require_int(settings_raw['tau'], 0, 1000000, 'tau')
        self.gamma = require_fraction(settings_raw['gamma'], 1, 1, 'gamma')
        self.cache_slots = require_int(settings_raw['cache_slots'], 0, 8,
                                       'cache_slots')

        self.demands = {}
        self.counters = {}
        self.routes = None
        self.snapshots = {}
        self._cache = OrderedDict()

    # ---------------------------------------------------------------- events

    def replay(self, events):
        if not isinstance(events, list):
            raise DomainError('events must be an array')
        answers = []
        for event in events:
            if not isinstance(event, dict):
                raise DomainError('event must be an object')
            op = event.get('op')
            if op == 'patch':
                answers.append(self._apply_patch(event))
            elif op == 'routes':
                answers.append(self._apply_routes(event))
            elif op == 'repair':
                answers.append(self._apply_repair(event))
            elif op == 'validate':
                answers.append(self._apply_validate(event))
            else:
                raise DomainError('unknown event op %r' % (op,))
        return answers

    def _apply_patch(self, event):
        reject = {'op': 'patch', 'accepted': False}
        if PATCH_FIELDS != frozenset(event.keys()):
            return reject
        demand_entries = event['demands']
        counter_entries = event['counters']
        if not isinstance(demand_entries, list):
            return reject
        if not isinstance(counter_entries, dict):
            return reject

        topo = self.topo
        external = topo.external_id_set
        pending_demands = {}
        for entry in demand_entries:
            if not isinstance(entry, list) or len(entry) != 3:
                return reject
            source, dest, value = entry
            if type(source) is not int or type(dest) is not int \
                    or type(value) is not int:
                return reject
            if source not in external or dest not in external \
                    or source == dest:
                return reject
            if value < 0 or value > MAX_TICKS:
                return reject
            if (source, dest) in pending_demands:
                return reject
            pending_demands[(source, dest)] = value

        key_to_flow = topo.key_to_flow
        caps = topo.flow_cap
        pending_counters = {}
        for key, cell in counter_entries.items():
            index = key_to_flow.get(key)
            if index is None:
                return reject
            if cell is None:
                pending_counters[key] = None
                continue
            if not isinstance(cell, dict):
                return reject
            cell_keys = frozenset(cell.keys())
            if 'perturbed' not in cell_keys:
                return reject
            if not cell_keys <= CELL_ANNOTATIONS:
                return reject
            perturbed = cell['perturbed']
            if perturbed is None:
                pending_counters[key] = None
                continue
            if type(perturbed) is not int:
                return reject
            capacity = caps[index]
            if perturbed < 0 or perturbed > capacity:
                return reject
            pending_counters[key] = perturbed

        demands = self.demands
        for pair, value in pending_demands.items():
            demands[pair] = value
        counters = self.counters
        for key, value in pending_counters.items():
            if value is None:
                counters.pop(key, None)
            else:
                counters[key] = value
        return {'op': 'patch', 'accepted': True}

    def _apply_routes(self, event):
        paths = event.get('paths')
        self.routes = normalize_routes(paths)
        return {'op': 'routes', 'accepted': True}

    def _apply_repair(self, event):
        snapshot_id = event.get('id')
        key = self._repair_key()
        cache = self._cache
        hit = key in cache
        if hit:
            result = cache[key]
            cache.move_to_end(key)
        else:
            result = compute_repair(self.topo, self.counters, self.demands,
                                    self.routes, self.seed, self.trials,
                                    self.epsilon)
            if self.cache_slots:
                cache[key] = result
                cache.move_to_end(key)
                while len(cache) > self.cache_slots:
                    cache.popitem(last=False)
        self.snapshots[snapshot_id] = result
        return self._repair_answer(snapshot_id, hit, result)

    def _apply_validate(self, event):
        snapshot_id = event.get('id')
        snapshot = self.snapshots.get(snapshot_id)
        topo = self.topo
        routes = self.routes
        if snapshot is None:
            return {'op': 'validate', 'id': snapshot_id, 'checked': 0,
                    'passed': 0, 'consistent': None, 'failed': []}

        predictions = compute_predictions(topo, self.demands, routes)
        counters = snapshot.counters
        key_list = topo.flow_key_list
        cut_num, cut_den = self.cutoff
        tau = self.tau
        scale = MILLION - self.bias
        checked = 0
        passed = 0
        failed = []
        for index, (source, target, _capacity) in enumerate(topo.flows):
            if routes is None and source != -1 and target != -1:
                continue
            predicted = predictions[(source, target)]
            expected = predicted * scale
            for key in key_list[index]:
                value, num, den = counters[key]
                if num * cut_den < cut_num * den:
                    continue
                checked += 1
                corrected = value * MILLION
                if corrected > expected:
                    larger = corrected
                else:
                    larger = expected
                if MILLION * abs(corrected - expected) <= tau * larger:
                    passed += 1
                else:
                    failed.append(key)
        failed.sort()
        consistent = None
        if checked:
            gamma_num, gamma_den = self.gamma
            consistent = passed * gamma_den >= checked * gamma_num
        return {'op': 'validate', 'id': snapshot_id, 'checked': checked,
                'passed': passed, 'consistent': consistent, 'failed': failed}

    # ------------------------------------------------------------- internals

    def _repair_key(self):
        return (
            self.topo.norm,
            tuple(sorted(self.counters.items())),
            tuple(sorted((pair, value) for pair, value in self.demands.items()
                         if value)),
            self.routes,
            self.seed,
            self.trials,
            self.epsilon,
        )

    @staticmethod
    def _repair_answer(snapshot_id, hit, result):
        pairs = result.pairs
        values = result.values
        confs = result.confs
        links = [[pairs[index][0], pairs[index][1], values[index],
                  confs[index][0], confs[index][1]]
                 for index in range(len(pairs))]
        order = [[pair[0], pair[1]] for pair in result.order]
        counters = {}
        for key, (value, num, den) in result.counters.items():
            counters[key] = {'corrected': value, 'confidence': [num, den]}
        return {'op': 'repair', 'id': snapshot_id, 'cache_hit': hit,
                'links': links, 'order': order, 'counters': counters}


def run_request(request):
    """Process one parsed request document into its result document."""
    if not isinstance(request, dict):
        raise DomainError('request must be an object')
    streams = request.get('streams')
    if not isinstance(streams, list):
        raise DomainError('streams must be an array')
    results = []
    for stream in streams:
        if not isinstance(stream, dict):
            raise DomainError('stream must be an object')
        for field in ('topology', 'settings', 'events'):
            if field not in stream:
                raise DomainError('stream field %s missing' % field)
        state = StreamState(stream['topology'], stream['settings'])
        results.append({'events': state.replay(stream['events'])})
    return {'streams': results}

